    const warn = sinon.stub(console, 'warn')

    const game = renderGame()

    // A one-move replay doesn't end the game
    const prompt = sinon.stub(window, 'prompt')
    prompt.returns('D')
    await user.click(screen.getByTestId('replay-button'))
    assert.deepEqual(prompt.getCalls().map(call => call.args), [
      ['Paste replay string...']
    ])
    prompt.restore()

    // The replay plays its single move and control
    // returns to the player
    await advanceReplaySteps(2)

    const replayingText = screen.queryByText('replaying...')
    const downCount = screen.queryAllByTestId('down').length

    // and the player can actually play
    await user.keyboard('{Down}')
    const downCountAfterMove = screen.queryAllByTestId('down').length
    const warnCount = warn.getCalls().length

    game.unmount()
    warn.restore()

    assert.equal(replayingText, null)
    assert.equal(downCount, 1)
    assert.equal(downCountAfterMove, 1)
    assert.equal(warnCount, 0)
  })

